var area=function(feature){
  var sup=ee.Feature(feature).set({areaHa: feature.geometry().area(10).divide(100 * 100)})
  return sup
}
var samples_area =samples.map(area)

var samples_polygon = samples_area.filter(ee.Filter.gt('areaHa',0));
print(samples_polygon.size(),"samples_polygon")

var buff=function(feature){
  var sup=ee.Feature(feature).buffer(100)
  return sup
}

var Chequeado_puntos = Chequeado.map(area).filter(ee.Filter.eq('areaHa',0))
var chequeado_buff1985 = Chequeado_puntos.map(buff)

print(chequeado_buff1985, "chequeado_buff1985")

var samples_polygon_cheq1985 = samples_polygon.filterBounds(chequeado_buff1985).merge(poligonos_te).merge(perennial_crops)
print(samples_polygon_cheq1985.size(),"samples_polygon_cheq1985")
print(samples_polygon_cheq1985, "samples_polygon_cheq1985")


var cheq2000 = Chequeado_2000.merge(Chequeado_2000_2)
var chequeado_buff2000 = cheq2000.map(buff)

print(chequeado_buff2000, "chequeado_buff2000")

var samples_polygon_cheq2000 = samples_polygon.filterBounds(chequeado_buff2000)
print(samples_polygon_cheq2000.size(),"samples_polygon_cheq2000")

Export.table.toAsset({
    "collection": ee.FeatureCollection(samples_polygon_cheq1985),
    "description": region_name + region_number2 + "_Coleccion5_1985",
    "assetId": outputAsset + region_name + region_number2 + "_Coleccion5_1985"
});

Export.table.toAsset({
    "collection": ee.FeatureCollection(samples_polygon_cheq2000),
    "description": region_name + region_number2 + "_Coleccion5_2000",
    "assetId": outputAsset + region_name + region_number2 + "_Coleccion5_2000"
})

